<?php
require_once __DIR__.'/helpers.php';$ok='';$err='';$edit=null;
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();try{$action=$_POST['action']??'';if($action==='save'){$id=(int)($_POST['id']??0);$q=trim((string)($_POST['question']??''));$a=trim((string)($_POST['answer']??''));$st=($_POST['status']??'active')==='inactive'?'inactive':'active';$sort=max(0,(int)($_POST['sort_order']??0));if($q===''||$a==='')throw new RuntimeException('Question and answer are required.');if(mb_strlen($q)>500||mb_strlen($a)>10000)throw new RuntimeException('Question or answer is too long.');if($id){$s=$pdo->prepare('UPDATE faqs SET question=?,answer=?,status=?,sort_order=? WHERE id=?');$s->execute([$q,$a,$st,$sort,$id]);$ok='FAQ updated.';}else{$s=$pdo->prepare('INSERT INTO faqs(question,answer,status,sort_order) VALUES(?,?,?,?)');$s->execute([$q,$a,$st,$sort]);$ok='FAQ added.';}}elseif($action==='delete'){$s=$pdo->prepare('DELETE FROM faqs WHERE id=?');$s->execute([(int)$_POST['id']]);$ok='FAQ deleted.';}}catch(Throwable $e){error_log($e->getMessage());$err=$e instanceof RuntimeException?$e->getMessage():'Could not process FAQ.';}}
if(isset($_GET['edit'])){$s=$pdo->prepare('SELECT * FROM faqs WHERE id=?');$s->execute([(int)$_GET['edit']]);$edit=$s->fetch(PDO::FETCH_ASSOC)?:null;}
$list=$pdo->query('SELECT * FROM faqs ORDER BY sort_order,id DESC')->fetchAll(PDO::FETCH_ASSOC);
page_start('Manage FAQ');if($ok)echo '<div class="notice">'.ce($ok).'</div>';if($err)echo '<div class="notice error">'.ce($err).'</div>';?>
<form method="post" class="card"><?=csrf()?><h2><?=$edit?'Edit FAQ':'Add New FAQ'?></h2><input type="hidden" name="action" value="save"><input type="hidden" name="id" value="<?=(int)($edit['id']??0)?>">
<div class="field"><label>Question</label><input name="question" maxlength="500" required value="<?=ce($edit['question']??'')?>"></div>
<div class="field"><label>Answer</label><textarea name="answer" maxlength="10000" required><?=ce($edit['answer']??'')?></textarea></div>
<div class="grid"><div class="field"><label>Status</label><select name="status"><option value="active" <?=($edit['status']??'active')==='active'?'selected':''?>>Active</option><option value="inactive" <?=($edit['status']??'')==='inactive'?'selected':''?>>Inactive</option></select></div><div class="field"><label>Sort Order (smaller first)</label><input type="number" min="0" name="sort_order" value="<?=(int)($edit['sort_order']??0)?>"></div></div>
<button class="btn"><?=$edit?'Update FAQ':'Add FAQ'?></button><?php if($edit):?> <a class="btn secondary" href="faq.php">Cancel</a><?php endif;?></form>
<div class="card"><h2>All FAQs (<?=count($list)?>)</h2><div class="table-wrap"><table><tr><th>Question</th><th>Status</th><th>Order</th><th>Action</th></tr><?php foreach($list as $r):?><tr><td><b><?=ce($r['question'])?></b><br><span class="muted"><?=ce(mb_strimwidth($r['answer'],0,110,'…'))?></span></td><td><?=ce($r['status'])?></td><td><?=(int)$r['sort_order']?></td><td><div class="actions"><a class="btn secondary" href="?edit=<?=(int)$r['id']?>">Edit</a><form method="post" onsubmit="return confirm('Delete this FAQ?')"><?=csrf()?><input type="hidden" name="action" value="delete"><input type="hidden" name="id" value="<?=(int)$r['id']?>"><button class="btn danger">Delete</button></form></div></td></tr><?php endforeach;?></table></div></div>
<?php page_end();?>